import pytest
from parse_kv import parse_kv

def test_empty_string():
    """Test that an empty string yields an empty dictionary."""
    assert parse_kv("") == {}

def test_basic_parsing():
    """Test basic key=value separation."""
    assert parse_kv("key1=value1") == {"key1": "value1"}
    assert parse_kv("key1=value1;key2=value2") == {"key1": "value1", "key2": "value2"}

def test_whitespace_trimming():
    """Test that keys and values are trimmed of whitespace."""
    assert parse_kv(" key1 = value1;key2 =  value2 ") == {"key1": "value1", "key2": "value2"}
    assert parse_kv(" key1=value1") == {"key1": "value1"}

def test_escaped_semicolon():
    """Test that backslash-escaped semicolons are treated as literal semicolons in the value."""
    # The value should contain a literal semicolon
    assert parse_kv("key1=value\\;part1;key2=value2") == {"key1": "value;part1", "key2": "value2"}
    assert parse_kv("key1=value\\;with\\;escapes") == {"key1": "value;with;escapes"}

def test_only_semicolons():
    """Test multiple semicolons that should be ignored if they don't form pairs."""
    assert parse_kv("a=b;;c=d") == {"a": "b", "c": "d"}

def test_mixed_content():
    """Test complex parsing with trimming and escaped semicolons."""
    test_string = "  key_a = value_a ; key_b = value_b\\;with\\;semicolon ; key_c = simple_c ;   "
    expected = {
        "key_a": "value_a",
        "key_b": "value_b;with;semicolon",
        "key_c": "simple_c"
    }
    assert parse_kv(test_string) == expected

def test_only_separators():
    """Test input consisting only of separators and whitespace."""
    assert parse_kv(" ; ; ") == {}

def test_no_equals_sign():
    """Test handling of segments without an equals sign (should be ignored)."""
    assert parse_kv("key1=value1;just_text;key2=value2") == {"key1": "value1", "key2": "value2"}

def test_value_with_equals():
    """Test that only the first '=' splits the key from the value."""
    assert parse_kv("key1=value=with=equals") == {"key1": "value=with=equals"}

